import { useId } from 'react';
import { LOGO_SHAPES } from '../../assets/brand/logo-data';
import styles from './Logo.module.css';

export type LogoVariant = keyof typeof LOGO_SHAPES;

interface LogoProps {
  variant?: LogoVariant;
  /** Accessible name (the brand name, not translated). */
  title?: string;
  className?: string;
}

/**
 * The Kinemax logo as inline SVG (outlined Cormorant Garamond, generated by
 * scripts/brand/generate-brand.mjs). Size it with CSS (height or width); it scales from its viewBox.
 */
export function Logo({ variant = 'horizontal', title = 'Kinemax', className }: LogoProps) {
  const titleId = useId();
  const shape = LOGO_SHAPES[variant];
  return (
    <svg
      className={[styles.logo, className].filter(Boolean).join(' ')}
      viewBox={shape.viewBox}
      role="img"
      aria-labelledby={titleId}
      data-variant={variant}
    >
      <title id={titleId}>{title}</title>
      <circle
        className={styles.ring}
        cx={shape.ring.cx}
        cy={shape.ring.cy}
        r={shape.ring.r}
        fill="none"
        strokeWidth={shape.ring.stroke}
      />
      <path className={styles.ivory} d={shape.ivory} />
      <path className={styles.crimson} d={shape.crimson} />
    </svg>
  );
}
